function loadModal(){const ss=slots(),e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="panel"><div class="panelHead"><button class="close">×</button><h2>Load Studio</h2><p>Choose a saved career.</p></div><div class="slots">${Array.from({length:5},(_,i)=>{const s=ss[i];return s?`<div class="slot"><div><h3>${esc(s.studioName)}</h3><p>Year ${s.year} · Week ${s.week} · $${Number(s.money).toLocaleString()}</p></div><div class="slotActions"><button class="mini gold" data-load="${i}">LOAD</button><button class="mini" data-del="${i}">DELETE</button></div></div>`:`<div class="slot empty"><div><h3>Slot ${i+1}</h3><p>Empty</p></div></div>`}).join('')}</div></div>`;document.body.appendChild(e);e.querySelector('.close').onclick=()=>e.remove();e.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{const s=slots()[+b.dataset.load];e.remove();start(s)});e.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{const i=+b.dataset.del;if(confirm('Delete this studio save?')){const x=slots();x[i]=null;write(x);e.remove();loadModal()}})}
const HOOK_BASES=['A teacher finds a recording from a former student, reopening a tragedy the town agreed to forget.','A broke performer gets one final chance after a rival steals the idea that could save a career.','A young doctor discovers a patient knows a secret about her family that should be impossible.','A widowed father receives letters from someone claiming to know his missing daughter.','Two strangers wake up with the same photograph and no memory of taking it.','A small town celebrates its oldest tradition until one night exposes the lie holding everyone together.','A journalist follows an anonymous tip that leads to a powerful figure protecting a dangerous secret.','A retired soldier returns home when a childhood friend asks for help with an impossible debt.','A teenager discovers an abandoned building contains evidence that could change the town forever.','A couple planning their future find an old diary that predicts choices they have not made yet.','A quiet employee realizes the company has been erasing one person from its own records.','A failed inventor builds something useful, only to learn another person has been waiting for it.','A musician hears a melody that appears in dreams and leads toward someone who disappeared years ago.','A family reunion turns strange when a guest arrives carrying a secret everyone thought was buried.','A teacher and former student cross paths again after one becomes powerful and the other needs help.','A delivery driver receives one package with no address and a warning never to open it.','A grieving sibling learns the person they blamed for a loss may have been protecting them.','A group of friends reunites for one night and discovers one member has secretly changed the past.','A struggling business owner gets an offer that could save everything but demands one impossible favor.','A lonely child befriends a stranger who seems to know every detail of a future that has not happened.'];const HOOK_FRAMES={Drama:['In a character-driven drama, ','The truth forces a painful choice between comfort and honesty.'],Comedy:['In a fast, chaotic comedy, ','What follows turns a simple problem into a chain of absurd consequences.'],Action:['In an explosive action film, ','The discovery puts innocent lives in immediate danger.'],Horror:['In a slow-burn horror story, ','The discovery awakens a threat the town thought was gone.'],Romance:['In a sweeping romance, ','The secret changes what both people believe love should cost.'],Thriller:['In a tense thriller, ','Every answer creates another question, and time is running out.'],['Sci-Fi']:['In a high-concept sci-fi mystery, ','The discovery suggests reality itself may be hiding the truth.'],Fantasy:['In an epic fantasy adventure, ','The revelation sends them toward a conflict bigger than their world.'],Animation:['In an animated family adventure, ','The mystery becomes a journey about courage, family, and belonging.'],Crime:['In a crime mystery, ','The clue connects to a crime powerful people desperately want buried.'],Adventure:['In a globe-spanning adventure, ','Their pursuit becomes a race against rivals, time, and impossible odds.']};function randomGenreHook(genre,used){const f=HOOK_FRAMES[genre]||HOOK_FRAMES.Drama;const available=HOOK_BASES.map((_,i)=>i).filter(i=>!used.has(i));const i=available.length?available[Math.floor(Math.random()*available.length)]:Math.floor(Math.random()*HOOK_BASES.length);used.add(i);const out=`${f[0]}${HOOK_BASES[i]}${f[1]}`;return out.length>200?out.slice(0,199)+'…':out;}document.addEventListener('click',function(ev){const b=ev.target.closest?.('#boxMagicBtn');if(!b)return;ev.preventDefault();ev.stopImmediatePropagation();const modal=b.closest('.movieModal');if(!modal)return;const genre=modal.querySelector('#movieGenre')?.value||'Drama';const hook=modal.querySelector('#movieHook');if(!hook)return;b._hookUsed=b._hookUsed||new Set();hook.value=randomGenreHook(genre,b._hookUsed);hook.dispatchEvent(new Event('input',{bubbles:true}));const label=modal.querySelector('.boxMagicResults');if(label)label.innerHTML='<div class="boxMagicChosen">✓ Random hook selected from 20 genre-specific story ideas. You can edit it.</div>';},{capture:true});window.showWeeklyReport=showWeeklyReport;
